#include <vector>
#include <map>

class Solution {
public:
    int smallestUniqueSubarray(std::vector<int>& nums) {
        int n = nums.size();
        int low = 1, high = n, ans = n;

        auto hasUnique = [&](int len) -> bool {
            std::map<std::vector<int>, int> counts;
            for (int i = 0; i <= n - len; ++i) {
                std::vector<int> sub(nums.begin() + i, nums.begin() + i + len);
                counts[sub]++;
            }
            for (const auto& [k, v] : counts) {
                if (v == 1) return true;
            }
            return false;
        };

        while (low <= high) {
            int mid = (low + high) / 2;
            if (hasUnique(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int smallestUniqueSubarray(int[] nums) {
        int n = nums.length;
        int low = 1, high = n, ans = n;

        while (low <= high) {
            int mid = (low + high) / 2;
            if (hasUnique(nums, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean hasUnique(int[] nums, int len) {
        int n = nums.length;
        Map<List<Integer>, Integer> counts = new HashMap<>();
        for (int i = 0; i <= n - len; i++) {
            List<Integer> sub = new ArrayList<>(len);
            for (int j = 0; j < len; j++) sub.add(nums[i + j]);
            counts.put(sub, counts.getOrDefault(sub, 0) + 1);
        }
        for (int c : counts.values()) {
            if (c == 1) return true;
        }
        return false;
    }
}

